ies improve material handling operations.',NULL,NULL,NULL,NULL,NULL,0,1,100,'2026-05-11 12:39:57','2026-05-11 12:39:57'),(1041,'High Temperature Weather Resistant EPDM Rubber','high-temperature-weather-resistant-epdm-rubber',1009,NULL,NULL,NULL,NULL,NULL,NULL,0,1,100,'2026-05-11 12:40:45','2026-05-11 12:40:45'),(1042,'Soft Temperature Silicone Rubber Sheets and Strips','soft-temperature-silicone-rubber-sheets-and-strips',1009,NULL,NULL,NULL,NULL,NULL,NULL,0,1,100,'2026-05-11 12:41:23','2026-05-11 12:41:23'),(1043,'Oil Resistant Buna-N Rubber Sheets and Strips','oil-resistant-buna-n-rubber-sheets-and-strips-1',1009,NULL,NULL,NULL,NULL,NULL,NULL,0,1,100,'2026-05-11 12:41:48','2026-05-11 12:41:48'),(1044,'Textured Multipurpose Neoprene Rubber','textured-multipurpose-neoprene-rubber-1',1009,NULL,NULL,NULL,NULL,NULL,NULL,0,1,100,'2026-05-11 12:42:35','2026-05-11 12:42:35'),(1045,'Fabric Reinforced Neoprene Rubber','fabric-reinforced-neoprene-rubber-1',1009,NULL,NULL,NULL,NULL,NULL,NULL,0,1,100,'2026-05-11 12:43:06','2026-05-11 12:43:06'),(1046,'Abrasion Resistant SBR Rubber Sheets and Strips','abrasion-resistant-sbr-rubber-sheets-and-strips-1',1009,NULL,NULL,NULL,NULL,NULL,NULL,0,1,100,'2026-05-11 12:43:42','2026-05-11 12:43:42'),(1047,'High Strength Oil Resistant Buna-N Rubber','high-strength-oil-resistant-buna-n-rubber',1009,NULL,NULL,NULL,NULL,NULL,NULL,0,1,100,'2026-05-11 12:44:11','2026-05-11 12:44:11'),(1048,'Ultra High Strength Polyurethane Rubber Sheets and Strips','ultra-high-strength-polyurethane-rubber-sheets-and-strips',1009,NULL,NULL,NULL,NULL,NULL,NULL,0,1,100,'2026-05-11 12:44:48','2026-05-11 12:44:48'),(1049,'Fiberglass Fabric-Reinforced Silicone Rubber','fiberglass-fabric-reinforced-silicone-rubber-1',1009,NULL,NULL,NULL,NULL,NULL,NULL,0,1,100,'2026-05-11 12:45:51','2026-05-11 12:45:51'),(1050,'Elastic Natural Rubber','elastic-natural-rubber-1',1009,NULL,NULL,NULL,NULL,NULL,NULL,0,1,100,'2026-05-11 12:46:13','2026-05-11 12:46:13'),(1051,'Elastic Natural 